function main(args) {
  const input = args.params.input;

  // Handle different possible structures
  let outputText = '';

  if (typeof input === 'string') {
    outputText = input;
  } else if (input && input.output) {
    outputText = input.output;
  } else if (input) {
    outputText = JSON.stringify(input);
  }

  // Extract filename using regex
  const match = outputText.match(/`([^`]+\.py)`/);

  const fileName = match ? match[1] : null;

  return {
    result: fileName
  };
}
